#!/usr/bin/env python3
"""
Round 132b (culprits-tiles-more), 2 October 2026.

oceans_more.py: marine heat falls back to Coral Reef Watch's own file server
when ERDDAP does not answer; acidification looks through the accession's
sub-folders for its NetCDF files and logs them; shipping moves out.
ocean_shipping.py (new): ship traffic as its own job, built kind by kind
within a time budget.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/oceans_more.py': '', 'scripts/ocean_shipping.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round132b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round132b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
